rows as (
  select case when t='DODO' then 'st-dodo-'||lower(substr(code,6)) else 'st-'||code end id, * from src)
insert into app.records (collection, id, data)
select 'stations', id, jsonb_strip_nulls(jsonb_build_object(
  'id', id, 'code', code, 'name', name, 'status', 'ACTIVE', 'siteType', t, 'region', region,
  'location', case when region is not null then region||', Oman' when t='DODO' then 'Oman — region and code to confirm' else 'B2B customer site, Oman' end,
  'vendor', vendor, 'vendorCompanyId', vco,
  'source', case when t='B2B' then 'B2B Site List R1 (01.11.2026)' else 'Site List (Regions) B2C' end))
from rows
on conflict (collection, id) do update set data = app.records.data || excluded.data;

-- The four demo stations are no longer needed
update app.records set data = data || '{"status":"INACTIVE"}'::jsonb
 where collection = 'stations' and id in ('stn-alpha','stn-beta','stn-gamma','stn-delta');

